## Code Example
```c
// Pseudo-code sketch (not complete, for illustration)
struct Slot { uint64_t seq; uint8_t data[64]; };
Slot buffer[N];
_Atomic uint64_t tail = 0;
_Atomic uint64_t head = 0;

void* log_dequeue(void* out, size_t* len) {
  uint64_t h = atomic_load(&head);
  uint64_t pos = h & (N-1);
  if (buffer[pos].seq != h+1) return NULL;
  memcpy(out, buffer[pos].data, 64);
  *len = 64;
  atomic_store_explicit(&buffer[pos].seq, h+N, memory_order_release);
  atomic_store_explicit(&head, h+1, memory_order_relaxed);
  return out;
}

int log_enqueue(const void* msg, size_t len) {
  if (len > 64) return -1;
  uint64_t t = atomic_fetch_add(&tail, 1);
  uint64_t pos = t & (N-1);
  while (buffer[pos].seq != t) _mm_pause();
  memcpy(buffer[pos].data, msg, 64);
  atomic_store_explicit(&buffer[pos].seq, t+1, memory_order_release);
  return 0;
}
```

